// SPDX-License-Identifier: MIT

pragma solidity 0.8.18;



/*

* @author not-so-secure-dev

* @title PasswordStore

* @notice This contract allows you to store a private password that others won&#039;t be able to see.

* You can update your password at any time.

*/

contract PasswordStore {

error PasswordStore__NotOwner();



/*//////////////////////////////////////////////////////////////

STORAGE VARIABLES

//////////////////////////////////////////////////////////////*/



address private s_owner;

// @audit the s_password variable is not actually private! This is

// not safe place to secure you password!

string private s_password;



/*//////////////////////////////////////////////////////////////

EVENTS

//////////////////////////////////////////////////////////////*/



event SetNetPassword();



constructor() {

s_owner = msg.sender;

}



/*

* @notice This function allows only the owner to set a new password.

* @param newPassword The new password to set.

*/

// @Audit - High - any user can set a password

// missing access control

function setPassword(string memory newPassword) external {

s_password = newPassword;

emit SetNetPassword();

}



/*

* @notice This allows only the owner to retrieve the password.

// @audit their is no newPassword parameter!

* @param newPassword The new password to set.

*/

function getPassword() external view returns (string memory) {

if (msg.sender != s_owner) {

revert PasswordStore__NotOwner();

}

return s_password;

}

}
